#!/usr/bin/env python3
"""Offline SIP identity boundary processor (PROTOCOL.md, revision 1).

Reads one JSON batch object on stdin, writes one JSON object on stdout.
Standard library only, no network, no child processes.
"""
import json
import re
import sys

# ---------------------------------------------------------------- constants

ANON = "sip:anonymous@anonymous.invalid"

MAX_REQUEST_CHARS = 32768
MAX_PHYSICAL_LINES = 512
MAX_LOGICAL_FIELDS = 128
MAX_TAG_LEN = 128
MAX_CALLID_LEN = 128
MAX_HOST_LEN = 253
MAX_LABEL_LEN = 63
MAX_TEL_DIGITS = 15

# Token characters: ASCII letters/digits and - . ! % * _ + ` ' ~
TOKEN_CHARS = frozenset(
    "[REDACTED:SECRET]`'~")
# USER characters: ASCII letters/digits and - _ . ! ~ * ' ( ) +
USER_CHARS = frozenset(
    "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_.!~*'()+")
ALNUM = frozenset(
    "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789")
HEXDIGITS = frozenset("0123456789abcdefABCDEF")

COMPACT = {
    "f": "from",
    "t": "to",
    "i": "call-id",
    "l": "content-length",
    "c": "content-type",
}

RE_LINE = re.compile(r"[\t\x20-\x7e]*\Z")
RE_BODY = re.compile(r"[\t\n\r\x20-\x7e]*\Z")
RE_CALLID = re.compile(r"[A-Za-z0-9_.@+-]{1,128}\Z")
RE_DIGITS = re.compile(r"[0-9]+\Z")
RE_CSEQ = re.compile(r"([0-9]+)[ \t]+([^ \t]*)\Z")
RE_CTYPE = re.compile(r"[\t\x20-\x7e]+\Z")


class BadSyntax(Exception):
    """Raised for any request grammar violation."""


def _skip_ws(s, i):
    n = len(s)
    while i < n and (s[i] == " " or s[i] == "\t"):
        i += 1
    return i


def _expand(name):
    low = name.lower()
    return COMPACT.get(low, low)


# ---------------------------------------------------------------- URI layer

def _normalize_host(host):
    if not host:
        raise BadSyntax()
    if host.endswith("."):
        host = host[:-1]
    if not host or len(host) > MAX_HOST_LEN:
        raise BadSyntax()
    for label in host.split("."):
        if not (1 <= len(label) <= MAX_LABEL_LEN):
            raise BadSyntax()
        if label[0] not in ALNUM or label[-1] not in ALNUM:
            raise BadSyntax()
        for ch in label:
            if ch not in ALNUM and ch != "-":
                raise BadSyntax()
    return host.lower()


def _decode_user(user):
    out = []
    i = 0
    n = len(user)
    while i < n:
        ch = user[i]
        if ch == "%":
            if i + 2 >= n:
                raise BadSyntax()
            h1 = user[i + 1]
            h2 = user[i + 2]
            if h1 not in HEXDIGITS or h2 not in HEXDIGITS:
                raise BadSyntax()
            val = int(h1 + h2, 16)
            if val > 127 or chr(val) not in USER_CHARS:
                raise BadSyntax()
            out.append(chr(val))
            i += 3
        elif ch in USER_CHARS:
            out.append(ch)
            i += 1
        else:
            raise BadSyntax()
    if not out:
        raise BadSyntax()
    return "".join(out)


def _parse_sip_rest(rest):
    """Return (user, host, consumed) for the text after 'sip:'."""
    i = 0
    n = len(rest)
    while i < n:
        ch = rest[i]
        if ch == "%":
            if i + 2 < n and rest[i + 1] in HEXDIGITS and rest[i + 2] in HEXDIGITS:
                i += 3
            else:
                raise BadSyntax()
        elif ch in USER_CHARS:
            i += 1
        else:
            break
    if i >= n or rest[i] != "@":
        raise BadSyntax()
    user = rest[:i]
    j = i + 1
    k = j
    while k < n and (rest[k] in ALNUM or rest[k] == "-" or rest[k] == "."):
        k += 1
    host = rest[j:k]
    return _decode_user(user), _normalize_host(host), k


def _parse_tel_rest(rest):
    """Return (digits, consumed) for the text after 'tel:'."""
    n = len(rest)
    if n == 0 or rest[0] != "+":
        raise BadSyntax()
    i = 1
    while i < n and "0" <= rest[i] <= "9":
        i += 1
    digits = rest[1:i]
    if not (1 <= len(digits) <= MAX_TEL_DIGITS):
        raise BadSyntax()
    if digits[0] == "0":
        raise BadSyntax()
    return digits, i


def _parse_uri_at(s, start):
    """Parse a URI at s[start]; return (normalized_uri, end_index)."""
    idx = s.find(":", start)
    if idx < 0:
        raise BadSyntax()
    scheme = s[start:idx].lower()
    rest = s[idx + 1:]
    if scheme == "sip":
        user, host, used = _parse_sip_rest(rest)
        return "sip:" + user + "@" + host, idx + 1 + used
    if scheme == "tel":
        digits, used = _parse_tel_rest(rest)
        return "tel:+" + digits, idx + 1 + used
    raise BadSyntax()


def _parse_uri_full(s):
    uri, end = _parse_uri_at(s, 0)
    if end != len(s):
        raise BadSyntax()
    return uri


def _norm_identity(value):
    """Normalized form of a directory/account identity string."""
    if not isinstance(value, str):
        return value
    try:
        return _parse_uri_full(value)
    except BadSyntax:
        return value


def _identity_domain(identity):
    if not isinstance(identity, str):
        return None
    idx = identity.rfind("@")
    if idx < 0:
        return None
    return identity[idx + 1:]


# ------------------------------------------------------------ address layer

def _parse_quoted(s, i):
    """Parse a quoted display string starting at s[i] == '"'."""
    n = len(s)
    i += 1
    while True:
        if i >= n:
            raise BadSyntax()
        ch = s[i]
        if ch == '"':
            return i + 1
        if ch == "\\":
            i += 1
            if i >= n:
                raise BadSyntax()
            nxt = s[i]
            if nxt != "\t" and not (0x20 <= ord(nxt) <= 0x7E):
                raise BadSyntax()
            i += 1
            continue
        if ch != "\t" and not (0x20 <= ord(ch) <= 0x7E):
            raise BadSyntax()
        i += 1


def _parse_bracketed(s, i):
    """Parse '<URI>' at s[i]; return (uri, end_index)."""
    n = len(s)
    j = i + 1
    while True:
        if j >= n:
            raise BadSyntax()
        ch = s[j]
        if ch == ">":
            break
        if ch == "<" or (ch != "\t" and not (0x20 <= ord(ch) <= 0x7E)):
            raise BadSyntax()
        j += 1
    content = s[i + 1:j].strip(" \t")
    if not content:
        raise BadSyntax()
    return _parse_uri_full(content), j + 1


def _parse_display_tokens(s, i):
    """Parse an unquoted display name (one or more tokens); return end index."""
    n = len(s)
    if i >= n or s[i] not in TOKEN_CHARS:
        raise BadSyntax()
    while True:
        while i < n and s[i] in TOKEN_CHARS:
            i += 1
        j = _skip_ws(s, i)
        if j < n and s[j] in TOKEN_CHARS:
            i = j
            continue
        return i


def _parse_address(s, pos, allow_tag):
    """Parse one address at s[pos]; return (uri, tag_or_None, end_index)."""
    n = len(s)
    pos = _skip_ws(s, pos)
    if pos >= n:
        raise BadSyntax()
    ch = s[pos]
    if ch == '"':
        pos = _parse_quoted(s, pos)
        pos = _skip_ws(s, pos)
        if pos >= n or s[pos] != "<":
            raise BadSyntax()
        uri, pos = _parse_bracketed(s, pos)
    elif ch == "<":
        uri, pos = _parse_bracketed(s, pos)
    else:
        head = s[pos:pos + 4].lower()
        if head == "sip:" or head == "tel:":
            uri, pos = _parse_uri_at(s, pos)
        else:
            pos = _parse_display_tokens(s, pos)
            pos = _skip_ws(s, pos)
            if pos >= n or s[pos] != "<":
                raise BadSyntax()
            uri, pos = _parse_bracketed(s, pos)
    tag = None
    p = _skip_ws(s, pos)
    if p < n and s[p] == ";":
        if not allow_tag:
            raise BadSyntax()
        p += 1
        p = _skip_ws(s, p)
        start = p
        while p < n and s[p] in TOKEN_CHARS:
            p += 1
        if p == start:
            raise BadSyntax()
        name = s[start:p]
        if name.lower() != "tag":
            raise BadSyntax()
        p = _skip_ws(s, p)
        if p >= n or s[p] != "=":
            raise BadSyntax()
        p += 1
        p = _skip_ws(s, p)
        start = p
        while p < n and s[p] in TOKEN_CHARS:
            p += 1
        if p == start:
            raise BadSyntax()
        tag = s[start:p]
        if len(tag) > MAX_TAG_LEN:
            raise BadSyntax()
        pos = p
    else:
        pos = p
    return uri, tag, pos


def _parse_single_address(value, allow_tag):
    uri, tag, pos = _parse_address(value, 0, allow_tag)
    pos = _skip_ws(value, pos)
    if pos != len(value):
        raise BadSyntax()
    return uri, tag


def _parse_address_list(value):
    """Parse a comma separated address list (no header parameters)."""
    out = []
    pos = 0
    n = len(value)
    while True:
        uri, _tag, pos = _parse_address(value, pos, False)
        out.append(uri)
        pos = _skip_ws(value, pos)
        if pos >= n:
            break
        if value[pos] != ",":
            raise BadSyntax()
        pos = _skip_ws(value, pos)
        if pos >= n or value[pos] == ",":
            raise BadSyntax()
    return out


# ------------------------------------------------------------- header layer

def _split_header_line(line):
    n = len(line)
    i = 0
    while i < n and line[i] in TOKEN_CHARS:
        i += 1
    if i == 0:
        raise BadSyntax()
    name = line[:i]
    j = _skip_ws(line, i)
    if j >= n or line[j] != ":":
        raise BadSyntax()
    return name, line[j + 1:]


class Request(object):
    __slots__ = ("method", "ruri", "from_uri", "from_tag", "to_uri", "to_tag",
                 "call_id", "cseq", "privacy", "ppi", "rpid", "pai", "ctype",
                 "body")


def _parse_request(text):
    if len(text) > MAX_REQUEST_CHARS:
        raise BadSyntax()
    idx = text.find("\r\n\r\n")
    if idx < 0:
        raise BadSyntax()
    head = text[:idx]
    body = text[idx + 4:]
    lines = head.split("\r\n")
    if lines and lines[-1] == "":
        lines.pop()
    if not lines or len(lines) > MAX_PHYSICAL_LINES:
        raise BadSyntax()
    for line in lines:
        if not RE_LINE.match(line):
            raise BadSyntax()
    if not RE_BODY.match(body):
        raise BadSyntax()

    req = Request()
    req.body = body

    parts = lines[0].split(" ")
    if len(parts) != 3:
        raise BadSyntax()
    method, ruri_raw, version = parts
    if method not in ("INVITE", "MESSAGE"):
        raise BadSyntax()
    if version != "SIP/2.0":
        raise BadSyntax()
    if not ruri_raw:
        raise BadSyntax()
    ruri = _parse_uri_full(ruri_raw)
    if not ruri.startswith("sip:"):
        raise BadSyntax()
    req.method = method
    req.ruri = ruri

    fields = []
    for line in lines[1:]:
        if line[0] == " " or line[0] == "\t":
            if not fields:
                raise BadSyntax()
            fields[-1][1] = fields[-1][1] + " " + line.lstrip(" \t")
        else:
            name, value = _split_header_line(line)
            fields.append([name, value])
    if len(fields) > MAX_LOGICAL_FIELDS:
        raise BadSyntax()

    by = {}
    for name, value in fields:
        by.setdefault(_expand(name), []).append(value.strip(" \t"))

    def single(key):
        vals = by.get(key)
        if not vals or len(vals) != 1:
            raise BadSyntax()
        return vals[0]

    def optional_single(key):
        vals = by.get(key)
        if not vals:
            return None
        if len(vals) != 1:
            raise BadSyntax()
        return vals[0]

    from_value = single("from")
    to_value = single("to")
    call_id = single("call-id")
    cseq_value = single("cseq")
    clen_value = single("content-length")

    req.from_uri, req.from_tag = _parse_single_address(from_value, True)
    req.to_uri, req.to_tag = _parse_single_address(to_value, True)

    if not RE_CALLID.match(call_id):
        raise BadSyntax()

    m = RE_CSEQ.match(cseq_value)
    if not m:
        raise BadSyntax()
    digits = m.group(1).lstrip("0") or "0"
    if m.group(2) != method:
        raise BadSyntax()
    if digits == "0" or len(digits) > 10 or int(digits) > 2147483647:
        raise BadSyntax()
    req.cseq = digits

    if not RE_DIGITS.match(clen_value):
        raise BadSyntax()
    want = str(len(body))
    if clen_value.lstrip("0") != want:
        raise BadSyntax()

    privacy = optional_single("privacy")
    if privacy is not None:
        low = privacy.lower()
        if low not in ("id", "none"):
            raise BadSyntax()
        privacy = low
    req.privacy = privacy

    ctype = optional_single("content-type")
    if ctype is not None:
        if not RE_CTYPE.match(ctype):
            raise BadSyntax()
    req.ctype = ctype

    ppi = optional_single("p-preferred-identity")
    if ppi is not None:
        ppi_uri, _tag = _parse_single_address(ppi, False)
        if ppi_uri == ANON:
            raise BadSyntax()
        req.ppi = ppi_uri
    else:
        req.ppi = None

    rpid = optional_single("remote-party-id")
    if rpid is not None:
        rpid_uri, _tag = _parse_single_address(rpid, False)
        if rpid_uri == ANON:
            raise BadSyntax()
        req.rpid = rpid_uri
    else:
        req.rpid = None

    pai = []
    for value in by.get("p-asserted-identity", []):
        pai.extend(_parse_address_list(value))
    if len(pai) not in (1, 2):
        raise BadSyntax()
    if len(pai) == 2:
        kinds = sorted(1 if u.startswith("sip:") else 2 for u in pai)
        if kinds != [1, 2]:
            raise BadSyntax()
    for uri in pai:
        if uri == ANON:
            raise BadSyntax()
    req.pai = pai
    return req


# ------------------------------------------------------------ identity layer

def _build_alias_map(directory):
    """Map every normalized alias to its canonical directory key."""
    amap = {}
    if not isinstance(directory, dict):
        return amap
    for key in directory:
        if not isinstance(key, str):
            continue
        norm = _norm_identity(key)
        if norm == ANON:
            continue
        if norm not in amap:
            amap[norm] = key
    for key, aliases in directory.items():
        if not isinstance(key, str):
            continue
        if not isinstance(aliases, list):
            continue
        for alias in aliases:
            if not isinstance(alias, str):
                continue
            norm = _norm_identity(alias)
            if norm == ANON or norm in amap:
                continue
            amap[norm] = key
    return amap


class Context(object):
    __slots__ = ("amap", "accounts", "gateways")

    def __init__(self, batch):
        directory = batch.get("directory")
        if not isinstance(directory, dict):
            directory = {}
        accounts = batch.get("accounts")
        if not isinstance(accounts, dict):
            accounts = {}
        gateways = batch.get("gateways")
        if not isinstance(gateways, dict):
            gateways = {}
        self.amap = _build_alias_map(directory)
        self.accounts = accounts
        self.gateways = gateways

    def resolve(self, uri):
        """Return the canonical directory key for a normalized claim URI."""
        if uri == ANON:
            return None
        return self.amap.get(uri)


def _reject(reason):
    return {"status": "reject", "reason": reason}, None


def _process_local(ctx, req, gateway, ingress):
    subject = ingress.get("subject")
    if not isinstance(subject, str):
        return _reject("unauthenticated")
    acct = ctx.accounts.get(subject)
    if not isinstance(acct, dict):
        return _reject("unauthenticated")
    primary = acct.get("primary")
    allow = acct.get("allow")
    allowed = set()
    if isinstance(primary, str):
        allowed.add(_norm_identity(primary))
    if isinstance(allow, list):
        for item in allow:
            if isinstance(item, str):
                allowed.add(_norm_identity(item))
    local_domains = gateway.get("local_domains")
    if not isinstance(local_domains, list):
        local_domains = []
    hosted = set(d for d in local_domains if isinstance(d, str))

    from_ident = None
    if req.from_uri != ANON:
        found = ctx.resolve(req.from_uri)
        if found is None:
            return _reject("identity")
        from_ident = _norm_identity(found)
        if from_ident not in allowed:
            return _reject("identity")
        if _identity_domain(from_ident) not in hosted:
            return _reject("identity")

    ppi_ident = None
    if req.ppi is not None:
        found = ctx.resolve(req.ppi)
        if found is None:
            return _reject("identity")
        ppi_ident = _norm_identity(found)
        if ppi_ident not in allowed:
            return _reject("identity")
        if _identity_domain(ppi_ident) not in hosted:
            return _reject("identity")

    if ppi_ident is not None:
        selected = ppi_ident
    elif from_ident is not None:
        selected = from_ident
    else:
        selected = _norm_identity(primary) if isinstance(primary, str) else None
    if selected is None or selected not in allowed:
        return _reject("identity")
    if _identity_domain(selected) not in hosted:
        return _reject("identity")
    return selected, "local"


def _process_peer(ctx, req, gateway, ingress):
    name = ingress.get("name")
    if not isinstance(name, str):
        return _reject("unauthenticated")
    peers = gateway.get("peers")
    if not isinstance(peers, dict):
        peers = {}
    if name not in peers:
        return _reject("unauthenticated")
    authority = peers.get(name)
    if not isinstance(authority, list):
        authority = []
    domains = set(d for d in authority if isinstance(d, str))

    if not req.pai:
        return _reject("unauthenticated")

    asserted = None
    for uri in req.pai:
        found = ctx.resolve(uri)
        if found is None:
            return _reject("identity")
        ident = _norm_identity(found)
        if _identity_domain(ident) not in domains:
            return _reject("identity")
        if asserted is None:
            asserted = ident
        elif asserted != ident:
            return _reject("identity")

    if req.from_uri != ANON:
        found = ctx.resolve(req.from_uri)
        if found is None or _norm_identity(found) != asserted:
            return _reject("identity")
    if req.ppi is not None:
        found = ctx.resolve(req.ppi)
        if found is None or _norm_identity(found) != asserted:
            return _reject("identity")
    if req.rpid is not None:
        found = ctx.resolve(req.rpid)
        if found is None or _norm_identity(found) != asserted:
            return _reject("identity")
    return asserted, "peer"


def _build_wire(req, selected, basis, private, trusted_out):
    lines = []
    lines.append("%s %s SIP/2.0" % (req.method, req.ruri))
    from_out = ANON if private else selected
    from_line = "From: <%s>" % from_out
    if req.from_tag:
        from_line += ";tag=%s" % req.from_tag
    lines.append(from_line)
    to_line = "To: <%s>" % req.to_uri
    if req.to_tag:
        to_line += ";tag=%s" % req.to_tag
    lines.append(to_line)
    lines.append("Call-ID: %s" % req.call_id)
    lines.append("CSeq: %s %s" % (req.cseq, req.method))
    lines.append("Privacy: %s" % ("id" if private else "none"))
    if (not private) or trusted_out:
        lines.append("P-Asserted-Identity: <%s>" % selected)
    if req.ctype is not None:
        lines.append("Content-Type: %s" % req.ctype)
    lines.append("Content-Length: %d" % len(req.body))
    return "\r\n".join(lines) + "\r\n\r\n" + req.body


def _process_job(ctx, job, wires):
    if not isinstance(job, dict):
        return _reject("syntax")
    if "source" in job and job["source"] is not None:
        src = job["source"]
        if not isinstance(src, int) or isinstance(src, bool):
            return _reject("upstream")
        if src < 0 or src >= len(wires):
            return _reject("upstream")
        text = wires[src]
        if text is None:
            return _reject("upstream")
    else:
        text = job.get("raw")
        if not isinstance(text, str):
            return _reject("syntax")

    try:
        req = _parse_request(text)
    except BadSyntax:
        return _reject("syntax")
    except RecursionError:
        return _reject("syntax")

    gateway_name = job.get("gateway")
    gateway = ctx.gateways.get(gateway_name) if isinstance(gateway_name, str) else None
    if not isinstance(gateway, dict):
        gateway = {}

    ingress = job.get("ingress")
    if not isinstance(ingress, dict):
        return _reject("unauthenticated")
    kind = ingress.get("kind")

    if kind == "local":
        outcome = _process_local(ctx, req, gateway, ingress)
    elif kind == "peer":
        outcome = _process_peer(ctx, req, gateway, ingress)
    else:
        return _reject("unauthenticated")
    if outcome is None:
        return _reject("identity")
    selected, basis = outcome
    if not isinstance(selected, str):
        return _reject("identity")

    private = (req.from_uri == ANON) or (req.privacy == "id")
    trusted_out = bool(job.get("trusted_out"))
    wire = _build_wire(req, selected, basis, private, trusted_out)
    result = {
        "status": "accept",
        "identity": selected,
        "basis": basis,
        "private": private,
        "wire": wire,
    }
    return result, wire


def process(batch):
    if not isinstance(batch, dict):
        batch = {}
    ctx = Context(batch)
    jobs = batch.get("jobs")
    if not isinstance(jobs, list):
        jobs = []
    results = []
    wires = []
    for job in jobs:
        result, wire = _process_job(ctx, job, wires)
        results.append(result)
        wires.append(wire)
    return {"results": results}


def main():
    data = sys.stdin.buffer.read()
    try:
        batch = json.loads(data.decode("utf-8"))
    except Exception:
        batch = {}
    out = process(batch)
    sys.stdout.write(json.dumps(out))
    sys.stdout.write("\n")
    sys.stdout.flush()
    return 0


if __name__ == "__main__":
    sys.exit(main())
